296	func PrintGlobalFactLine(out io.Writer, f factmerge.Record) {
297		marker := ""
298		switch f.Status {
299		case factmerge.StatusSuperseded:
300			marker = " (superseded)"
301		case factmerge.StatusRetracted:
302			marker = " (retracted)"
303		}
304		fmt.Fprintf(out, "%s %s [%s] (global)%s\n  %s\n", f.ID, factstore.KindOrInferred(f), strings.Join(f.Paths, ","), marker, f.Text)
305	}
