307	// SortedGlobalFactIDs returns the ids of the surfaced facts that are global, in
308	// the order they were surfaced, so JSON output is stable across runs.
309	func SortedGlobalFactIDs(matches []factmerge.Record, globalIDs map[string]bool) []string {
310		var ids []string
311		for _, f := range matches {
312			if globalIDs[f.ID] {
313				ids = append(ids, f.ID)
314			}
315		}
316		return ids
317	}
