319	// PrintFactLine renders a fact for human-readable listings.
320	func PrintFactLine(out io.Writer, f factmerge.Record) {
321		marker := ""
322		switch f.Status {
323		case factmerge.StatusSuperseded:
324			marker = " (superseded)"
325		case factmerge.StatusRetracted:
326			marker = " (retracted)"
327		}
328		fmt.Fprintf(out, "%s %s [%s]%s\n  %s\n", f.ID, factstore.KindOrInferred(f), strings.Join(f.Paths, ","), marker, f.Text)
329	}
