123	// an id the caller removed on purpose (gc, the mirror sweep) must not
124	// resurrect from a file nothing maintains anymore.
125	func Write(brainDir string, records []factmerge.Record) error {
126		return withRepoFactStoreLock(brainDir, func() error {
127			// Establish the pre-mutation migration before an intentional delete or
128			// retraction. Never merge legacy records into the caller's replacement set.
129			dirs, err := legacyBranchDirs(brainDir)
